147	  /** This person's grades: a claim is at the one in force on its date. */
148	  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
149	  /** The sheet's periods, by from-date. */
150	  readonly periods = input.required<readonly PeriodView[]>();
151	  /** The other people on the sheet a claim can be moved to. */
152	  readonly others = input<readonly Pick<PersonView, 'id' | 'name'>[]>([]);
153	  /** The person's holds: their open claims dated within one, and not bound by a statement, count in no total. */
154	  readonly holds = input<readonly HoldView[]>([]);
155	  /** The person's retirement date (null: not retired): once the sheet's today reaches it, their open claims not
156	   *  bound by a statement count in no total. */
157	  readonly retiredFrom = input<string | null>(null);
158	  /** The ids of the claims selected for a bulk action. */
159	  readonly selected = input<ReadonlySet<number>>(new Set());
160	  readonly saved = output<ClaimView>();
161	  readonly selectToggled = output<{ id: number; selected: boolean }>();
162	
163	  protected readonly notAvailable = NOT_AVAILABLE;
164	  protected readonly claimed = computed(() => money(this.claims().filter(countsWithHolds(this.holds(), this.sheets.current()?.today ?? '', this.retiredFrom())).reduce((sum, c) => sum + cents(c.amount), 0)));
165	  protected readonly editingId = signal<number | null>(null);
166	  /** Whether the form was typed into since the edit button was pressed. */
167	  private typedSinceEdit = false;
168	  protected readonly error = signal<string | null>(null);
169	  protected readonly saving = signal(false);
170	  /** The error of the last action taken on a claim's row, until the next action on that row. */
171	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
172	  /** The person chosen to move each claim to, by claim id. */
173	  protected readonly reassignTo = signal<Readonly<Record<number, string>>>({});
174	  /** The date typed to defer each OPEN claim until, by id. */
175	  protected readonly deferDates = signal<Readonly<Record<number, string>>>({});
176	  /** The new date typed for each OPEN or PENDING claim, by id. */
177	  protected readonly newDates = signal<Readonly<Record<number, string>>>({});
178	  /** The amount typed to split off each OPEN claim, by id. */
179	  protected readonly splitAmounts = signal<Readonly<Record<number, string>>>({});
180	  /** The reason typed to reject each PENDING claim, by id. */
181	  protected readonly rejectReasons = signal<Readonly<Record<number, string>>>({});
182	
183	  protected readonly form = new FormGroup({
184	    amount: new FormControl('', { nonNullable: true }),
185	    date: new FormControl('', { nonNullable: true }),
186	    note: new FormControl('', { nonNullable: true }),
187	    corrects: new FormControl('', { nonNullable: true }),
188	  });
189	
190	  constructor() {
191	    // An error is removed as soon as its form is changed.
192	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => {
193	      this.error.set(null);
194	      this.typedSinceEdit = true;
195	    });
196	    // A claim whose editor this user has open (it holds their lock) shows its editor again when the sheet is
197	    // re-loaded.
198	    effect(() => {
199	      const user = this.session.user();
200	      const mine = this.claims().find((c) => c.status === 'DRAFT' && c.lockedBy !== null && c.lockedBy === user);
201	      untracked(() => {
202	        if (mine && this.editingId() === null) this.open(mine);
203	      });
204	    });
205	  }
206	
207	  protected dueOf(c: ClaimView): string {
208	    const grade = gradeOn(this.grades(), c.date);
209	    const rates = this.ratesByGrade().get(grade) ?? NO_RATES;
210	    const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()), grade);
211	    return due === null ? NOT_AVAILABLE : money(due);
212	  }
213	
214	  protected dueByOf(c: ClaimView): string {
215	    return c.dueBy;
216	  }
217	
218	  protected overdueOf(c: ClaimView): boolean {
219	    const sheet = this.sheets.current();
220	    return sheet !== null && isOverdue(c, sheet.today, graceOn(sheet.settings, gradeOn(this.grades(), c.date), c.date));
221	  }
222	
223	  protected deferredOf(c: ClaimView): boolean {
224	    const sheet = this.sheets.current();
225	    return sheet !== null && isDeferred(c, sheet.today);
226	  }
227	
228	  protected deferDateChanged(c: ClaimView, date: string): void {
229	    this.deferDates.update((dates) => ({ ...dates, [c.id]: date }));
230	    if (this.claimError()?.id === c.id) this.claimError.set(null);
231	  }
232	
233	  protected defer(c: ClaimView): void {
234	    this.claimError.set(null);
235	    const sheet = this.sheets.current();
236	    if (!sheet) return;
237	    const until = (this.deferDates()[c.id] ?? '').trim();
238	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
239	      this.claimError.set({ id: c.id, message: 'Choose the date to defer the claim until.' });
240	      return;
241	    }
242	    this.api.defer(sheet.id, c.id, until).subscribe({
243	      next: (saved) => {
244	        this.deferDates.update((dates) => ({ ...dates, [c.id]: '' }));
245	        this.saved.emit(saved);
246	      },
247	      error: (err: unknown) => this.claimError.set({
248	        id: c.id,
249	        message: err instanceof HttpErrorResponse && err.status === 423
250	          ? 'This claim is due by inside a closed period.'
251	          : err instanceof HttpErrorResponse && err.status === 400
252	            ? `A claim is deferred to a day after today (${sheet.today}).`
253	            : `A ${c.status} claim cannot be deferred; only an OPEN one can.`,
254	      }),
255	    });
256	  }
257	
258	  protected newDateChanged(c: ClaimView, date: string): void {
259	    this.newDates.update((dates) => ({ ...dates, [c.id]: date }));
260	    if (this.claimError()?.id === c.id) this.claimError.set(null);
261	  }
262	
263	  protected redate(c: ClaimView): void {
264	    this.claimError.set(null);
265	    const sheet = this.sheets.current();
266	    if (!sheet) return;
267	    const date = (this.newDates()[c.id] ?? '').trim();
268	    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
269	      this.claimError.set({ id: c.id, message: 'Choose the new date of the claim.' });
270	      return;
271	    }
272	    this.api.redate(sheet.id, c.id, date).subscribe({
273	      next: (saved) => {
274	        this.newDates.update((dates) => ({ ...dates, [c.id]: '' }));
275	        this.saved.emit(saved);
276	      },
277	      error: (err: unknown) => this.claimError.set({
278	        id: c.id,
279	        message: err instanceof HttpErrorResponse && err.status === 403
280	          ? 'Only a steward can re-date a claim.'
281	          : err instanceof HttpErrorResponse && err.status === 423
282	            ? 'This claim is due by inside a closed period.'
283	            : err instanceof HttpErrorResponse && err.status === 422
284	              ? `${this.personName()} retired before ${date}.`
285	              : `A ${c.status} claim cannot be re-dated; only an OPEN or PENDING one can.`,
286	      }),
287	    });
288	  }
289	
290	  protected splitAmountChanged(c: ClaimView, amount: string): void {
291	    this.splitAmounts.update((amounts) => ({ ...amounts, [c.id]: amount }));
292	    if (this.claimError()?.id === c.id) this.claimError.set(null);
293	  }
294	
295	  protected split(c: ClaimView): void {
296	    this.claimError.set(null);
297	    const sheet = this.sheets.current();
298	    if (!sheet) return;
299	    const amount = (this.splitAmounts()[c.id] ?? '').trim();
300	    if (!AMOUNT_PATTERN.test(amount) || cents(amount) <= 0 || cents(amount) >= cents(c.amount)) {
301	      this.claimError.set({ id: c.id, message: `Type an amount more than 0.00 and less than ${c.amount} to split off.` });
302	      return;
303	    }
304	    this.api.split(sheet.id, c.id, amount).subscribe({
305	      next: (result) => {
306	        this.splitAmounts.update((amounts) => ({ ...amounts, [c.id]: '' }));
307	        this.saved.emit(result.original);
308	        this.saved.emit(result.split);
309	      },
310	      error: (err: unknown) => this.claimError.set({
311	        id: c.id,
312	        message: err instanceof HttpErrorResponse && err.status === 403
313	          ? 'Your role may not open a claim, so it may not split one.'
314	          : err instanceof HttpErrorResponse && err.status === 423
315	            ? 'This claim is due by inside a closed period.'
316	            : err instanceof HttpErrorResponse && err.status === 400
317	              ? `Type an amount more than 0.00 and less than ${c.amount} to split off.`
318	              : this.deferredOf(c)
319	                ? `This claim is deferred until ${c.deferredUntil}, so it cannot be split.`
320	                : `A ${c.status} claim cannot be split; only an OPEN one can.`,
321	      }),
322	    });
323	  }
324	
325	  protected periodOf(c: ClaimView): string {
326	    return periodOn(this.periods(), c.dueBy)?.name ?? '';
327	  }
328	
329	  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
330	    this.claimError.set(null);
331	    const sheet = this.sheets.current();
332	    if (!sheet) return;
333	    this.api.changeStatus(sheet.id, c.id, status).subscribe({
334	      next: (saved) => this.saved.emit(saved),
335	      error: (err: unknown) => this.claimError.set({
336	        id: c.id,
337	        message: err instanceof HttpErrorResponse && err.status === 403
338	          ? status === 'SETTLED' && c.openedBy === this.session.user()
339	            ? 'You opened this claim, so someone else must settle it.'
340	            : status === 'VOID' && c.status === 'SETTLED'
341	              ? 'Only a steward may void a settled claim.'
342	            : `Your role may not ${STATUS_ACTION[status] ?? 'move'} a claim.`
343	          : err instanceof HttpErrorResponse && err.status === 423
344	            ? 'This claim is due by inside a closed period.'
345	            : err instanceof HttpErrorResponse && err.status === 428
346	              ? status === 'OPEN' ? UNNOTED : UNPROVEN
347	            : status === 'VOID' && c.status === 'SETTLED'
348	              ? 'A settled claim can be voided only within 7 days of its settlement.'
349	            : status === 'SETTLED' && this.deferredOf(c)
350	              ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled before then.`
351	              : `A ${c.status} claim cannot become ${status}.`,
352	      }),
353	    });
354	  }
355	
356	  protected addProof(c: ClaimView): void {
357	    this.claimError.set(null);
358	    const sheet = this.sheets.current();
359	    if (!sheet) return;
360	    this.api.addProof(sheet.id, c.id).subscribe({
361	      next: (saved) => this.saved.emit(saved),
362	      error: (err: unknown) => this.claimError.set({
363	        id: c.id,
364	        message: err instanceof HttpErrorResponse && err.status === 423
365	          ? 'This claim is due by inside a closed period.'
366	          : `A ${c.status} claim cannot be given a proof.`,
367	      }),
368	    });
369	  }
370	
371	  protected remind(c: ClaimView): void {
372	    this.claimError.set(null);
373	    const sheet = this.sheets.current();
374	    if (!sheet) return;
375	    this.api.remind(sheet.id, c.id).subscribe({
376	      next: (saved) => this.saved.emit(saved),
377	      error: (err: unknown) => this.claimError.set({
378	        id: c.id,
379	        message: err instanceof HttpErrorResponse && err.status === 403
380	          ? 'You may not remind this claim.'
381	          : c.status === 'OPEN' || c.status === 'PENDING'
382	            ? 'This claim was already reminded today.'
383	            : `A ${c.status} claim cannot be reminded.`,
384	      }),
385	    });
386	  }
387	
388	  protected approve(c: ClaimView): void {
389	    this.claimError.set(null);
390	    const sheet = this.sheets.current();
391	    if (!sheet) return;
392	    this.api.approve(sheet.id, c.id).subscribe({
393	      next: (saved) => this.saved.emit(saved),
394	      error: (err: unknown) => this.claimError.set({
395	        id: c.id,
396	        message: err instanceof HttpErrorResponse && err.status === 403
397	          ? c.openedBy === this.session.user()
398	            ? 'You opened this claim, so another steward must approve it.'
399	            : 'Only a steward can approve a claim.'
400	          : this.refusal(err, c, 'approved'),
401	      }),
402	    });
403	  }
404	
405	  protected resettle(c: ClaimView): void {
406	    this.claimError.set(null);
407	    const sheet = this.sheets.current();
408	    if (!sheet) return;
409	    this.api.resettle(sheet.id, c.id).subscribe({
410	      next: (saved) => this.saved.emit(saved),
411	      error: (err: unknown) => this.claimError.set({
412	        id: c.id,
413	        message: err instanceof HttpErrorResponse && err.status === 403
414	          ? 'Only a steward can re-settle a claim.'
415	          : err instanceof HttpErrorResponse && err.status === 423
416	            ? 'This claim is due by inside a closed period.'
417	            : `A ${c.status} claim cannot be re-settled; only a SETTLED one can.`,
418	      }),
419	    });
420	  }
421	
422	  protected reasonChanged(c: ClaimView, reason: string): void {
423	    this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: reason }));
424	    if (this.claimError()?.id === c.id) this.claimError.set(null);

file.content:
  template: `
    <p>Claimed: <span data-testid="person-claimed">{{ claimed() }}</span></p>

    <form [formGroup]="form" (ngSubmit)="submit()"
          [attr.aria-label]="(editingId() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
      <label [for]="fieldId('amount')">Amount</label>
      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount"
             inputmode="decimal" autocomplete="off" />
      <label [for]="fieldId('date')">Date</label>
      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="fieldId('note')">Note</label>
      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" autocomplete="off" />
      <label [for]="fieldId('corrects')">Corrects claim No.</label>
      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects"
             inputmode="numeric" autocomplete="off" />
      <button type="submit" data-testid="claim-form-submit" [disabled]="saving()">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (error(); as err) {
        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
      }
    </form>

    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
                 (change)="selectToggled.emit({ id: c.id, selected: $any($event.target).checked })"
                 [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
          No. <span data-testid="claim-number">{{ c.number ?? '' }}</span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          on <span data-testid="claim-date">{{ c.date }}</span>
          — due <span data-testid="claim-due">{{ dueOf(c) }}</span>
          by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span>
          — overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span>
          in period <span data-testid="claim-period">{{ periodOf(c) }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          corrects No. <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span>
          <span data-testid="claim-status">{{ c.status }}</span>
          opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span>
          — stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span>
          — deferred <span data-testid="claim-deferred">{{ deferredOf(c) ? 'yes' : 'no' }}</span>
          until <span data-testid="claim-deferred-until">{{ c.deferredUntil ?? '' }}</span>
          <label [for]="'claim-defer-date-' + c.id">Defer until</label>
          <input [id]="'claim-defer-date-' + c.id" type="date" data-testid="claim-defer-date"
                 [value]="deferDates()[c.id] ?? ''" (input)="deferDateChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-defer" (click)="defer(c)"
                  [attr.aria-label]="'Defer claim of ' + c.amount + ' on ' + c.date">Defer</button>
          <label [for]="'claim-date-new-' + c.id">New date</label>
          <input [id]="'claim-date-new-' + c.id" type="date" data-testid="claim-date-new"
                 [value]="newDates()[c.id] ?? ''" (input)="newDateChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-redate" (click)="redate(c)"
                  [attr.aria-label]="'Re-date claim of ' + c.amount + ' on ' + c.date">Re-date</button>
          — proofs <span data-testid="claim-proofs">{{ c.proofs }}</span>
          <button type="button" data-testid="claim-proof" (click)="addProof(c)"
                  [attr.aria-label]="'Add a proof to claim of ' + c.amount + ' on ' + c.date">Add proof</button>
          — reminded <span data-testid="claim-reminded">{{ c.remindedOn ?? '' }}</span>
          <button type="button" data-testid="claim-remind" (click)="remind(c)"
                  [attr.aria-label]="'Remind claim of ' + c.amount + ' on ' + c.date">Remind</button>
          split from No. <span data-testid="claim-split-from">{{ c.splitFrom ?? '' }}</span>
          — late entry <span data-testid="claim-late-entry">{{ c.lateEntry ? 'yes' : 'no' }}</span>
          <label [for]="'claim-split-amount-' + c.id">Amount to split off</label>
          <input [id]="'claim-split-amount-' + c.id" data-testid="claim-split-amount" inputmode="decimal"
                 autocomplete="off" [value]="splitAmounts()[c.id] ?? ''"
                 (input)="splitAmountChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-split" (click)="split(c)"
                  [attr.aria-label]="'Split claim of ' + c.amount + ' on ' + c.date">Split</button>
          <button type="button" data-testid="claim-open" (click)="changeStatus(c, 'OPEN')"
                  [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
          <button type="button" data-testid="claim-settle" (click)="changeStatus(c, 'SETTLED')"
                  [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
          <button type="button" data-testid="claim-approve" (click)="approve(c)"
                  [attr.aria-label]="'Approve claim of ' + c.amount + ' on ' + c.date">Approve</button>
          <button type="button" data-testid="claim-resettle" (click)="resettle(c)"
                  [attr.aria-label]="'Re-settle claim of ' + c.amount + ' on ' + c.date">Re-settle</button>
          <label [for]="'claim-reject-reason-' + c.id">Reason to reject</label>
          <input [id]="'claim-reject-reason-' + c.id" data-testid="claim-reject-reason" autocomplete="off"
                 [value]="rejectReasons()[c.id] ?? ''" (input)="reasonChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-reject" (click)="reject(c)"
                  [attr.aria-label]="'Reject claim of ' + c.amount + ' on ' + c.date">Reject</button>
          <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'VOID')"
                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
          <select [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to"
                  [value]="reassignTo()[c.id] ?? ''" (change)="reassignToChanged(c, $any($event.target).value)">
            <option value="">Choose a person</option>
            @for (o of others(); track o.id) {
              <option [value]="o.id">{{ o.name }}</option>
            }
          </select>
          <button type="button" data-testid="claim-reassign" (click)="reassign(c)"
                  [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
          @if (editingId() === c.id) {
            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
          } @else {
            <button type="button" data-testid="claim-edit" (click)="edit(c)"
                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          }
          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
            @for (l of c.log; track $index) {
              <li data-testid="claim-log-line">{{ l.status }} by {{ l.by }} on {{ l.on }} due={{ l.due ?? notAvailable }}</li>
            }
          </ol>
          @if (claimError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly sheets = inject(Sheets);
  private readonly session = inject(Session);
  private readonly api = inject(Claims);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<ClaimView[]>();
  /** The rates of each grade, in the order they take effect. */
  readonly ratesByGrade = input.required<ReadonlyMap<Grade, readonly RateView[]>>();
  /** This person's grades: a claim is at the one in force on its date. */
  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
  /** The sheet's periods, by from-date. */
  readonly periods = input.required<readonly PeriodView[]>();
  /** The other people on the sheet a claim can be moved to. */
  readonly others = input<readonly Pick<PersonView, 'id' | 'name'>[]>([]);
  /** The person's holds: their open claims dated within one, and not bound by a statement, count in no total. */
  readonly holds = input<readonly HoldView[]>([]);
  /** The person's retirement date (null: not retired): once the sheet's today reaches it, their open claims not
   *  bound by a statement count in no total. */
  readonly retiredFrom = input<string | null>(null);
  /** The ids of the claims selected for a bulk action. */
  readonly selected = input<ReadonlySet<number>>(new Set());
  readonly saved = output<ClaimView>();
  readonly selectToggled = output<{ id: number; selected: boolean }>();

  protected readonly notAvailable = NOT_AVAILABLE;
  protected readonly claimed = computed(() => money(this.claims().filter(countsWithHolds(this.holds(), this.sheets.current()?.today ?? '', this.retiredFrom())).reduce((sum, c) => sum + cents(c.amount), 0)));
  protected readonly editingId = signal<number | null>(null);
  /** Whether the form was typed into since the edit button was pressed. */
  private typedSinceEdit = false;
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The error of the last action taken on a claim's row, until the next action on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  /** The person chosen to move each claim to, by claim id. */
  protected readonly reassignTo = signal<Readonly<Record<number, string>>>({});
  /** The date typed to defer each OPEN claim until, by id. */
  protected readonly deferDates = signal<Readonly<Record<number, string>>>({});
  /** The new date typed for each OPEN or PENDING claim, by id. */
  protected readonly newDates = signal<Readonly<Record<number, string>>>({});
  /** The amount typed to split off each OPEN claim, by id. */
  protected readonly splitAmounts = signal<Readonly<Record<number, string>>>({});
  /** The reason typed to reject each PENDING claim, by id. */
  protected readonly rejectReasons = signal<Readonly<Record<number, string>>>({});

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
    corrects: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => {
      this.error.set(null);
      this.typedSinceEdit = true;
    });
    // A claim whose editor this user has open (it holds their lock) shows its editor again when the sheet is
    // re-loaded.
    effect(() => {
      const user = this.session.user();
      const mine = this.claims().find((c) => c.status === 'DRAFT' && c.lockedBy !== null && c.lockedBy === user);
      untracked(() => {
        if (mine && this.editingId() === null) this.open(mine);
      });
    });
  }

  protected dueOf(c: ClaimView): string {
    const grade = gradeOn(this.grades(), c.date);
    const rates = this.ratesByGrade().get(grade) ?? NO_RATES;
    const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()), grade);
    return due === null ? NOT_AVAILABLE : money(due);
  }

  protected dueByOf(c: ClaimView): string {
    return c.dueBy;
  }

  protected overdueOf(c: ClaimView): boolean {
    const sheet = this.sheets.current();
    return sheet !== null && isOverdue(c, sheet.today, graceOn(sheet.settings, gradeOn(this.grades(), c.date), c.date));
  }

  protected deferredOf(c: ClaimView): boolean {
    const sheet = this.sheets.current();
    return sheet !== null && isDeferred(c, sheet.today);
  }

  protected deferDateChanged(c: ClaimView, date: string): void {
    this.deferDates.update((dates) => ({ ...dates, [c.id]: date }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);
  }

  protected defer(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const until = (this.deferDates()[c.id] ?? '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
      this.claimError.set({ id: c.id, message: 'Choose the date to defer the claim until.' });
      return;
    }
    this.api.defer(sheet.id, c.id, until).subscribe({
      next: (saved) => {
        this.deferDates.update((dates) => ({ ...dates, [c.id]: '' }));
        this.saved.emit(saved);
      },
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 423
          ? 'This claim is due by inside a closed period.'
          : err instanceof HttpErrorResponse && err.status === 400
            ? `A claim is deferred to a day after today (${sheet.today}).`
            : `A ${c.status} claim cannot be deferred; only an OPEN one can.`,
      }),
    });
  }

  protected newDateChanged(c: ClaimView, date: string): void {
    this.newDates.update((dates) => ({ ...dates, [c.id]: date }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);
  }

  protected redate(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const date = (this.newDates()[c.id] ?? '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.claimError.set({ id: c.id, message: 'Choose the new date of the claim.' });
      return;
    }
    this.api.redate(sheet.id, c.id, date).subscribe({
      next: (saved) => {
        this.newDates.update((dates) => ({ ...dates, [c.id]: '' }));
        this.saved.emit(saved);
      },
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? 'Only a steward can re-date a claim.'
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 422
              ? `${this.personName()} retired before ${date}.`
              : `A ${c.status} claim cannot be re-dated; only an OPEN or PENDING one can.`,
      }),
    });
  }

  protected splitAmountChanged(c: ClaimView, amount: string): void {
    this.splitAmounts.update((amounts) => ({ ...amounts, [c.id]: amount }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);
  }

  protected split(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const amount = (this.splitAmounts()[c.id] ?? '').trim();
    if (!AMOUNT_PATTERN.test(amount) || cents(amount) <= 0 || cents(amount) >= cents(c.amount)) {
      this.claimError.set({ id: c.id, message: `Type an amount more than 0.00 and less than ${c.amount} to split off.` });
      return;
    }
    this.api.split(sheet.id, c.id, amount).subscribe({
      next: (result) => {
        this.splitAmounts.update((amounts) => ({ ...amounts, [c.id]: '' }));
        this.saved.emit(result.original);
        this.saved.emit(result.split);
      },
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? 'Your role may not open a claim, so it may not split one.'
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 400
              ? `Type an amount more than 0.00 and less than ${c.amount} to split off.`
              : this.deferredOf(c)
                ? `This claim is deferred until ${c.deferredUntil}, so it cannot be split.`
                : `A ${c.status} claim cannot be split; only an OPEN one can.`,
      }),
    });
  }

  protected periodOf(c: ClaimView): string {
    return periodOn(this.periods(), c.dueBy)?.name ?? '';
  }

  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.changeStatus(sheet.id, c.id, status).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? status === 'SETTLED' && c.openedBy === this.session.user()
            ? 'You opened this claim, so someone else must settle it.'
            : status === 'VOID' && c.status === 'SETTLED'
              ? 'Only a steward may void a settled claim.'
            : `Your role may not ${STATUS_ACTION[status] ?? 'move'} a claim.`
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 428
              ? status === 'OPEN' ? UNNOTED : UNPROVEN
            : status === 'VOID' && c.status === 'SETTLED'
              ? 'A settled claim can be voided only within 7 days of its settlement.'
            : status === 'SETTLED' && this.deferredOf(c)
              ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled before then.`
              : `A ${c.status} claim cannot become ${status}.`,
      }),
    });
  }

  protected addProof(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.addProof(sheet.id, c.id).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 423
          ? 'This claim is due by inside a closed period.'
          : `A ${c.status} claim cannot be given a proof.`,
      }),
    });
  }

  protected remind(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.remind(sheet.id, c.id).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? 'You may not remind this claim.'
          : c.status === 'OPEN' || c.status === 'PENDING'
            ? 'This claim was already reminded today.'
            : `A ${c.status} claim cannot be reminded.`,
      }),
    });
  }

  protected approve(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.approve(sheet.id, c.id).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? c.openedBy === this.session.user()
            ? 'You opened this claim, so another steward must approve it.'
            : 'Only a steward can approve a claim.'
          : this.refusal(err, c, 'approved'),
      }),
    });
  }

  protected resettle(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.resettle(sheet.id, c.id).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? 'Only a steward can re-settle a claim.'
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : `A ${c.status} claim cannot be re-settled; only a SETTLED one can.`,
      }),
    });
  }

  protected reasonChanged(c: ClaimView, reason: string): void {
    this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: reason }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);

